<script setup lang="ts">import type{Activity}from'../types';import{date,activityState,activityImage}from'../utils';import Icon from './Icon.vue';defineProps<{activity:Activity}>();defineEmits<{select:[activity:Activity]}>()</script>
<template><button class="activity-card" @click="$emit('select',activity)"><div class="activity-image"><img :src="activityImage(activity)" alt="征途骑行插画" loading="lazy"><span class="image-label">{{activity.category}}</span><span class="activity-date"><b>{{new Date(activity.startsAt).getDate()}}</b><small>{{new Date(activity.startsAt).getMonth()+1}} 月</small></span></div><div class="activity-card-body"><span class="category-label">{{activity.clubName}}</span><h3>{{activity.title}}</h3><p><Icon name="pin" :size="14"/>{{activity.location}}</p><div class="activity-card-footer"><span>{{date(activity.startsAt)}} · {{activity.registrationCount}}/{{activity.capacity}} 人</span><span :class="{'text-green':activityState(activity)==='报名中'}">{{activityState(activity)}}<Icon name="arrowup" :size="15"/></span></div></div></button></template>
